<template>
	<view class="school">
		<view class="banner">
			<image src="/static/images/fujinxiaoqu2.png" mode="widthFix"></image>
		</view>

		<view class="list">
			<view class="item" v-for="item in list" :key="item.campusId">
				<view class="title">{{item.campusName}}</view>
				<view class="address-box">
					<text class="iconfont icon-weizhi"></text>
					<view class="address">{{item.campusAddress}}</view>
					<!-- <view class="km">12.6km</view> -->
				</view>
				<view class="tel">
					<text class="iconfont icon-dianhua3"></text>{{item.campusPhone}}
				</view>
			</view>
		</view>


		<!-- 		加载提示 -->
		<view class="loading" v-if="showLoading">
			<text style="--i:1">加</text>
			<text style="--i:2">载</text>
			<text style="--i:3">中</text>
			<text style="--i:4">.</text>
			<text style="--i:5">.</text>
			<text style="--i:6">.</text>
		</view>
		<view class="end" v-if="showNone">暂无更多...</view>
	</view>
</template>
<script>
	import {
		loaded,
		loading,
		toast,
		redirectTo,
		navigateTo
	} from '@/utils/index.js';
	import {
		img_PATH
	} from '@/config';
	import {
		queryCampusList
	} from '@/api/index.js'
	export default {
		data() {
			return {
				imgurl: img_PATH,
				CustomBar: this.CustomBar,
				showLoading: false,
				showNone: false,
				page: 1,
				limit: 20,
				cityId: '',
				list: []
			};
		},
		computed: {

		},
		components: {

		},
		onLoad(options) {
			this.cityId = options.cityId ? options.cityId : ''
			this.getList()
		},
		created() {

		},
		// 触底的事件
		onReachBottom() {

		},
		methods: {
			async getList() {
				this.showNone = false
				this.showLoading = true
				let _data = await queryCampusList(this.cityId);
				if (_data.code == 200) {
					if (_data.data.length === 0) {
						this.showLoading = false
						this.showNone = true
					} else {
						this.showLoading = false
						this.list = _data.data
					}

				}
			},
			to(path) {
				navigateTo(path)
			},
		},

	}
</script>

<style scoped lang="scss">
	.school {
		min-height: 100vh;
		width: 100%;
		padding: 30rpx 25rpx;
		background-color: #f7f7f7;

		.list {
			width: 100%;
			background: #ffffff;
			padding: 25rpx;
			margin-top: 30rpx;
			border-radius: 20rpx;

			.item {
				width: 100%;
				padding: 28rpx;
				background-color: #f8f9fc;
				border-radius: 20rpx;
				margin-bottom: 20rpx;

				.tel {
					width: 100%;
					display: flex;
					justify-content: flex-start;
					align-items: center;
					font-size: 26rpx;
					color: #1f89f6;

					.icon-dianhua3 {
						font-size: 34rpx;
						color: #1f89f6;
						margin-right: 12rpx;
					}
				}

				.address-box {
					width: 100%;
					display: flex;
					justify-content: space-between;
					align-items: center;
					padding: 20rpx 0;

					.km {
						text-align: right;
						width: 150rpx;
						font-size: 26rpx;
						color: #888c99;
					}

					.address {
						flex: 1;
						padding: 0 10rpx;
						font-size: 26rpx;
						color: #888c99;
					}

					.icon-weizhi {
						font-size: 34rpx;
						color: #333333;
					}
				}

				.title {
					width: 100%;
					font-size: 32rpx;
					color: #2b2e48;
					font-weight: bold;
				}
			}
		}

		.banner {
			width: 100%;

			image {
				width: 100%;
				height: auto;
			}
		}

	}
</style>